"""DesignStudio brand tokens (v3.30). Writes brand/tokens/tokens.json, tokens.css and contrast.json. Run: python3 brand/build_tokens.py"""
import json, os
H = os.path.dirname(__file__); os.makedirs(os.path.join(H, 'tokens'), exist_ok=True)
def rgb(h): h = h.lstrip('#'); return [int(h[i:i+2], 16) / 255 for i in (0, 2, 4)]
def hexs(c): return '#' + ''.join(f'{round(max(0, min(1, v)) * 255):02X}' for v in c)
def lin(v): return v / 12.92 if v <= .04045 else ((v + .055) / 1.055) ** 2.4
def L(h): r, g, b = (lin(v) for v in rgb(h)); return .2126 * r + .7152 * g + .0722 * b
def cr(a, b): la, lb = sorted((L(a), L(b)), reverse=True); return round((la + .05) / (lb + .05), 2)
def mix(a, b, t): return hexs([x + (y - x) * t for x, y in zip(rgb(a), rgb(b))])
def scale(base, dark):
    # 50..900 around a 500 base: tints towards white, shades towards a deep tone of the same hue
    return {50: mix(base, '#FFFFFF', .92), 100: mix(base, '#FFFFFF', .82), 200: mix(base, '#FFFFFF', .64), 300: mix(base, '#FFFFFF', .42),
            400: mix(base, '#FFFFFF', .2), 500: base, 600: mix(base, dark, .22), 700: mix(base, dark, .42), 800: mix(base, dark, .62), 900: mix(base, dark, .8)}
palette = {
    'blue': scale('#3A8BFF', '#071A45'),      # Design blue — primary, "design" start
    'violet': scale('#6B4FF0', '#140A45'),    # Studio violet — "design" end, media accents
    'yellow': scale('#FFC21A', '#4A2E00'),    # Holy yellow — link nodes, highlights, never body text on light
    'pearl': {50: '#FDFBF5', 100: '#FAF6EA', 200: '#F4ECD6', 300: '#E9DDBA', 400: '#D6C595', 500: '#BCA772'},
    'ink': {50: '#F4F4F8', 100: '#E8E8EF', 200: '#C9C9D6', 300: '#9A9AB0', 400: '#6E6E80', 500: '#4A4A5A', 600: '#2B2B36', 700: '#1F1F28', 800: '#17171D', 900: '#0F0F14'},
}
semantic = {
    'brand-primary': palette['blue'][500], 'brand-secondary': palette['violet'][500], 'brand-node': palette['yellow'][500],
    'brand-node-on-light': '#F0A500', 'brand-pearl': palette['pearl'][200], 'brand-ink': palette['ink'][800],
    'gradient-design': f"linear-gradient(90deg, {palette['blue'][500]}, {palette['violet'][500]})",
    'success': '#2BB673', 'danger': '#F2545B', 'warning': palette['yellow'][500], 'info': palette['blue'][500],
    'surface-0': palette['ink'][900], 'surface-1': palette['ink'][800], 'surface-2': palette['ink'][700], 'surface-3': palette['ink'][600],
    'text-strong': palette['pearl'][50], 'text': palette['ink'][100], 'text-muted': palette['ink'][300],
}
type_ = {'display': "'Sora', 'Inter', system-ui, sans-serif", 'text': "'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif", 'mono': "ui-monospace, 'SF Mono', Consolas, monospace",
         'scale': {'display-xl': [72, 1.05, 800, -0.03], 'display': [48, 1.1, 700, -0.025], 'h1': [32, 1.2, 700, -0.02], 'h2': [24, 1.25, 600, -0.015], 'h3': [18, 1.35, 600, -0.01], 'body': [15, 1.55, 400, 0], 'small': [13, 1.5, 400, 0], 'caption': [11, 1.4, 600, 0.06]}}
space = [0, 4, 8, 12, 16, 24, 32, 48, 64, 96]; radius = {'sm': 6, 'md': 10, 'lg': 14, 'xl': 22, 'pill': 999}
motion = {'fast': '120ms', 'base': '200ms', 'slow': '360ms', 'ease-out': 'cubic-bezier(.2,.9,.3,1)', 'ease-pop': 'cubic-bezier(.2,.9,.3,1.6)', 'ease-in-out': 'cubic-bezier(.65,0,.35,1)'}
pairs = [('pearl-200 on ink-800', palette['pearl'][200], palette['ink'][800]), ('ink-100 on ink-800', palette['ink'][100], palette['ink'][800]),
         ('ink-300 on ink-800', palette['ink'][300], palette['ink'][800]), ('blue-400 on ink-800', palette['blue'][400], palette['ink'][800]),
         ('blue-500 on ink-800', palette['blue'][500], palette['ink'][800]), ('yellow-500 on ink-800', palette['yellow'][500], palette['ink'][800]),
         ('violet-300 on ink-800', palette['violet'][300], palette['ink'][800]), ('white on blue-600', '#FFFFFF', palette['blue'][600]),
         ('white on violet-500', '#FFFFFF', palette['violet'][500]), ('ink-800 on yellow-500', palette['ink'][800], palette['yellow'][500]),
         ('ink-800 on pearl-200', palette['ink'][800], palette['pearl'][200]), ('blue-700 on white', palette['blue'][700], '#FFFFFF'),
         ('yellow-500 on white', palette['yellow'][500], '#FFFFFF')]
contrast = [{'pair': n, 'fg': a, 'bg': b, 'ratio': cr(a, b), 'AA': cr(a, b) >= 4.5, 'AA-large': cr(a, b) >= 3} for n, a, b in pairs]
json.dump({'palette': palette, 'semantic': semantic, 'type': type_, 'space': space, 'radius': radius, 'motion': motion}, open(os.path.join(H, 'tokens/tokens.json'), 'w'), indent=2)
json.dump(contrast, open(os.path.join(H, 'tokens/contrast.json'), 'w'), indent=1)
css = [':root {', '  /* DesignStudio brand tokens v3.30 — generated by brand/build_tokens.py */']
for k, sc in palette.items(): css += [f'  --ds-{k}-{s}: {v};' for s, v in sc.items()]
css += [f'  --ds-{k}: {v};' for k, v in semantic.items()]
css += [f"  --ds-font-display: {type_['display']};", f"  --ds-font-text: {type_['text']};", f"  --ds-font-mono: {type_['mono']};"]
css += [f'  --ds-space-{i}: {v}px;' for i, v in enumerate(space)] + [f'  --ds-radius-{k}: {v}px;' for k, v in radius.items()] + [f'  --ds-motion-{k}: {v};' for k, v in motion.items()] + ['}']
open(os.path.join(H, 'tokens/tokens.css'), 'w').write('\n'.join(css) + '\n')
for c in contrast: print(f"{c['pair']:24} {c['ratio']:5}  {'AA' if c['AA'] else ('AA-large' if c['AA-large'] else 'FAIL')}")
